def parse_duration(text):
    """Converts a duration string into a whole number of seconds.

    The string is one or more `<integer><unit>` parts with no spaces,
    where the unit is `d` (86400 s), `h` (3600 s), `m` (60 s) or `s` (1 s).
    Units must appear in that order (days, hours, minutes, seconds) and
    each at most once, for example `"1h30m"`, `"2d"`, `"1d2h3m4s"`, `"0s"`.
    Anything else raises ValueError.

    Args:
        text: The duration string.

    Returns:
        The duration in seconds.

    Raises:
        ValueError: If the input string is invalid.
    """
    if not text:
        raise ValueError("Empty string")

    total_seconds = 0
    parts = text.split('')
    if not parts:
        raise ValueError("No units found")

    for part in parts:
        if len(part) == 1:
            if part == 'd':
                total_seconds += 86400
            elif part == 'h':
                total_seconds += 3600
            elif part == 'm':
                total_seconds += 60
            elif part == 's':
                total_seconds += 1
            else:
                raise ValueError("Unknown unit: {}".format(part))
        else:
            try:
                num = int(part[:-1])
                unit = part[-1]
                if unit == 'd':
                    total_seconds += num * 86400
                elif unit == 'h':
                    total_seconds += num * 3600
                elif unit == 'm':
                    total_seconds += num * 60
                elif unit == 's':
                    total_seconds += num
                else:
                    raise ValueError("Unknown unit: {}".format(unit))
            except ValueError:
                raise ValueError("Invalid number: {}".format(part))

    return total_seconds

def parse_csv_line(line):
    """Splits one line of CSV text into a list of field strings.

    Fields are separated by commas. A field may be wrapped in double quotes;
    inside a quoted field commas are literal and a doubled
    double quote (`""`) stands for one double quote. Unquoted fields are
    returned exactly as written (spaces are kept).
    An empty line gives `[""]`, and a trailing comma gives a trailing empty
    field. A quote that is never closed raises
    `ValueError`. The line contains no newlines.
    """
    if not line:
        return [""]

    fields = []
    in_quote = False
    current_field = ""
    for char in line:
        if char == '"':
            if in_quote:
                if char == '"':
                    current_field += char
                    in_quote = False
                else:
                    raise ValueError("Unclosed quote")
            else:
                in_quote = True
                current_field += char
        elif char == ',' and not in_quote:
            fields.append(current_field)
            current_field = ""
        else:
            current_field += char

    fields.append(current_field)
    return fields

