def toposort(deps):
    """
    Sorts a list of names based on their dependencies.

    Args:
        deps (dict): A dictionary mapping a name to a list of names it depends on.

    Returns:
        list: A list of all names, including names that only appear inside
              dependency lists, such that every name comes after everything it
              depends on. When several names are ready at the same time, choose
              the alphabetically smallest first.

    Raises:
        ValueError: If the dependencies contain a cycle.
    """
    graph = deps
    in_degree = {}
    for node in graph:
        in_degree[node] = 0
    for node in graph:
        for dep in graph[node]:
            if dep not in in_degree:
                in_degree[dep] = 0
            in_degree[node] += 1

    queue = []
    for node in in_degree:
        if in_degree[node] == 0:
            queue.append(node)

    result = []
    while queue:
        node = min(queue)
        queue.remove(node)
        result.append(node)
        for dependent in graph:
            if node in graph[dependent]:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    queue.append(dependent)

    if len(result) != len(in_degree):
        raise ValueError("Cycle detected")

    return result

class LRUCache:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity
        self.cache = {}
        self.queue = []

    def get(self, key):
        if key in self.cache:
            self.queue.remove(key)
            self.queue.append(key)
            return self.cache[key]
        else:
            return None

    def put(self, key, value):
        if key in self.cache:
            self.queue.remove(key)
            self.cache[key] = value
            self.queue.append(key)
        else:
            if len(self.cache) >= self.capacity:
                lru_key = self.queue.pop(0)
                del self.cache[lru_key]
            self.cache[key] = value
            self.queue.append(key)

    def __len__(self):
        return len(self.cache)

    def keys(self):
        return sorted(self.queue, key=lambda k: self.cache[k])

def flatten_dict(d, sep="."):
    items = []
    for k, v in d.items():
        new_key = k
        if isinstance(v, dict):
            for k2, v2 in flatten_dict(v, sep=sep).items():
                items.append((new_key + sep + k2, v2))
        else:
            items.append((new_key, v))
    return dict(items)

