from typing import Any, Dict

class TTLCache:
    def __init__(self, capacity: int, ttl: int, clock: callable = time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("TTL must be greater than 0")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache: Dict[Any, tuple[Any, float]] = {}
        self.usage_order = []

    def put(self, key: Any, value: Any):
        if key in self.cache:
            self.cache[key] = (value, self.clock())
            self.usage_order.append(key)
            return
        if len(self.cache) >= self.capacity:
            self._evict_oldest()
        self.cache[key] = (value, self.clock())
        self.usage_order.append(key)

    def get(self, key: Any) -> Any:
        if key in self.cache:
            value, expiry_time = self.cache[key]
            if self.clock() < expiry_time:
                self.usage_order.remove(key)
                self.usage_order.append(key)
                return value
            else:
                self._remove_key(key)
                return None
        else:
            return None

    def __len__(self) -> int:
        return len([entry for entry in self.cache if self.clock() < entry[1]])

    def keys(self) -> list[Any]:
        return [key for key in self.usage_order if key in self.cache and self.clock() < self.cache[key][1]]

    def _remove_key(self, key: Any):
        del self.cache[key]
        self.usage_order.remove(key)

    def _evict_oldest(self):
        while len(self.cache) >= self.capacity:
            oldest_key = self.usage_order[0]
            self._remove_key(oldest_key)

import heapq

class Scheduler:
    def __init__(self):
        self.tasks = []
        self.errors = []

    def schedule(self, name, run_at, callback, every=None):
        if every is not None and every <= 0:
            raise ValueError("every must be greater than 0")
        if any(t[1] == name for t in self.tasks):
            raise ValueError(f"Task with name '{name}' already exists")

        heapq.heappush(self.tasks, (run_at, name, callback, every))

    def cancel(self, name):
        original_length = len(self.tasks)
        self.tasks = [(at, n, cb, ev) for (at, n, cb, ev) in self.tasks if n != name]
        return original_length > len(self.tasks)

    def pending(self):
        return sorted(self.tasks, key=lambda x: (x[0], id(x[2])))

    def run_due(self, now):
        run_names = []
        new_tasks = []
        temp_tasks = []

        while self.tasks:
            at, name, callback, every = heapq.heappop(self.tasks)

            if at <= now:
                try:
                    callback()
                    run_names.append(name)
                except Exception as e:
                    self.errors.append((name, e))
            else:
                temp_tasks.append((at, name, callback, every))

        for at, name, callback, every in temp_tasks:
            heapq.heappush(self.tasks, (at, name, callback, every))

        return run_names

def evaluate(expr, variables=None):
    """Evaluates an arithmetic expression given as a string and returns the result as a float."""
    expr = expr.replace(" ", "")
    if not expr:
        raise ValueError("Empty expression")

    def precedence(op):
        if op == '^':
            return 3
        elif op == '+' or op == '-':
            return 2
        elif op == '*' or op == '/':
            return 1
        else:
            return 0

    def apply_op(op, val1, val2):
        if op == '+':
            return val1 + val2
        elif op == '-':
            return val1 - val2
        elif op == '*':
            return val1 * val2
        elif op == '/':
            if val2 == 0:
                raise ValueError("Division by zero")
            return val1 / val2
        elif op == '^':
            return val1 ** val2
        else:
            raise ValueError(f"Unknown operator: {op}")

    tokens = expr.split('+')
    if len(tokens) == 1:
        tokens = expr.split('-')
    if len(tokens) == 1:
        tokens = expr.split('*')
    if len(tokens) == 1:
        tokens = expr.split('/')
    if len(tokens) == 1:
        tokens = expr.split('^')

    values = []
    ops = []

    i = 0
    while i < len(tokens):
        if tokens[i].isdigit() or (tokens[i].startswith('-') and tokens[i][1:].isdigit()):
            val = float(tokens[i])
            values.append(val)
            i += 1
        elif tokens[i] == '(':
            ops.append(tokens[i])
            i += 1
        elif tokens[i] == ')':
            while len(ops) > 0 and ops[-1] != '(':
                val2 = values.pop()
                val1 = values.pop()
                op = ops.pop()
                values.append(apply_op(op, val1, val2))
            if len(ops) == 0:
                raise ValueError("Unbalanced parentheses")
            ops.pop()
            i += 1
        elif tokens[i] in ['+', '-', '*', '/', '^']:
            while len(ops) > 0 and precedence(ops[-1]) >= precedence(tokens[i]):
                val2 = values.pop()
                val1 = values.pop()
                op = ops.pop()
                values.append(apply_op(op, val1, val2))
            ops.append(tokens[i])
            i += 1
        else:
            raise ValueError(f"Unknown character: {tokens[i]}")

    while len(ops) > 0:
        val2 = values.pop()
        val1 = values.pop()
        op = ops.pop()
        values.append(apply_op(op, val1, val2))

    if len(values) != 1:
        raise ValueError("Invalid expression")

    return values[0]

def parse_ini(text):
    result = {}
    current_section = ""
    lines = text.splitlines()
    for i, line in enumerate(lines):
        line = line.strip()
        if not line:
            continue

        if line.startswith(";") or line.startswith("#"):
            continue

        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            if not section:
                raise ValueError(f"line {i+1}: section name cannot be empty")
            current_section = section
        elif current_section == "":
            key, value = line.split("=", 1)
            if not key.strip():
                raise ValueError(f"line {i+1}: key cannot be empty")
            result[current_section] = {key.strip(): value.strip()}
        elif line == "=":
            continue
        else:
            key, value = line.split("=", 1)
            if not key.strip():
                raise ValueError(f"line {i+1}: key cannot be empty")
            if value:
                if value.startswith('"'):
                    if value.count('"') % 2 != 0:
                        raise ValueError(f"line {i+1}: unterminated quoted value")
                    value = value[1:-1]
                    if value.startswith("\\"):
                        raise ValueError(f"line {i+1}: bad escape")
                    if not value:
                        raise ValueError(f"line {i+1}: empty quoted value")
                if value.startswith(";") or value.startswith("#"):
                    value = value[1:].strip()
                    if value:
                        raise ValueError(f"line {i+1}: comment after value")
                result[current_section][key.strip()] = value.strip()
            else:
                if value.startswith(";") or value.startswith("#"):
                    value = value[1:].strip()
                    if value:
                        raise ValueError(f"line {i+1}: comment after value")
                result[current_section][key.strip()] = ""

    return result

