class Inventory:
    def __init__(self, stock=None):
        if stock is None:
            self._stock = {}
        else:
            self._stock = stock.copy()

    def stock(self, item):
        return self._stock.get(item, 0)

    def add(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        self._stock[item] = self.stock(item) + qty

    def remove(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        current_stock = self.stock(item)
        if qty > current_stock:
            raise OutOfStock
        self._stock[item] = current_stock - qty

def render(template, context):
    def resolve_path(path, value):
        if not path:
            return ''
        parts = path.split('.')
        current = value
        for part in parts:
            try:
                if isinstance(current, dict) and part.isdigit():
                    current = current[int(part)]
                elif isinstance(current, list) and part.isdigit():
                    current = current[int(part)]
                else:
                    current = current.get(part)
            except (KeyError, IndexError, TypeError):
                return ''
            if current is None:
                return ''
        return current

    def apply_filter(value, filter_name):
        if filter_name == 'upper':
            if value is None:
                return ''
            return str(value).upper()
        elif filter_name == 'lower':
            if value is None:
                return ''
            return str(value).lower()
        elif filter_name == 'title':
            if value is None:
                return ''
            return str(value).title()
        elif filter_name == 'length':
            if value is None:
                return 0
            return len(value)
        else:
            raise ValueError(f"Unknown filter: {filter_name}")

    def render_block(block, context):
        if block.startswith('{{'):
            parts = block[2:-2].split('|')
            value = resolve_path(parts[0], context)
            filter_name = parts[1] if len(parts) > 1 else None
            if filter_name:
                value = apply_filter(value, filter_name)
            return str(value)
        elif block.startswith('{% if'):
            condition = block[3:-3]
            value = resolve_path([condition], context)
            return ' ' + (' ' if value else '') + ' ' + block[3:-3]
        elif block.startswith('{% for'):
            name = block[3:-3]
            items = resolve_path([name], context)
            if not items:
                return ''
            result = ''
            for item in items:
                result += render_block(block[3:-3], context)
            return result
        elif block.startswith('{% else'):
            return render_block(block[5:-3], context)
        elif block.startswith('{% endif'):
            return ''
        else:
            return block

    result = ''
    stack = []
