        char = template[i]
        if char == '{':
            if i + 1 < len(template) and template[i + 1] == '{':
                j = i + 2
                while j < len(template) and template[j] != '}':
                    j += 1
                if j < len(template) and template[j] == '}':
                    block = template[i + 2:j]
                    if block:
                        result += render_block(block, context)
                    i = j + 1
                else:
                    raise ValueError("Unclosed '{{'")
            else:
                result += char
                i += 1
        elif char == '}':
            if i > 0 and template[i - 1] == '{':
                result += char
                i += 1
            else:
                raise ValueError("Unclosed '}}'")
        else:
            result += char
            i += 1
    return result
